/// Validate the configuration, returning an error if any settings are invalid.
///
/// Checks:
/// - `ocr`: backend name, VLM backend/model requirements, language codes, and the
///   `vlm_fallback` quality threshold (see `OcrConfig.validate`).
/// - `chunking`: `max_characters` is non-zero and `overlap` is smaller than it.
/// - `token_reduction`: `mode` is one of the recognized reduction levels.
/// - `images`: `target_dpi`, `min_dpi`, and `max_dpi` are all positive and within the
///   supported range.
/// - `language_detection`: `min_confidence` is a `[0.0, 1.0]` value.
/// - `csv`: `delimiter`, when set, is exactly one ASCII character.
///
/// Called automatically when a config is loaded from a file
/// (`ExtractionConfig.from_file` and friends) or built from a JSON override
/// (`crate::core::config::merge::merge_config_json`). A config assembled directly through
/// the typed Rust API or an FFI builder is **not** automatically validated â call this
/// method explicitly before use in that case.
/// \note Returns `XbergError::Validation` describing the first invalid setting found.
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn xberg_extraction_config_validate(this: AlefHandle) -> i32 {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut __alef_requests: Vec<HandleRequest> = Vec::new();
        __alef_requests.push(HandleRequest {
            handle: this,
            expected_type: std::any::TypeId::of::<xberg::ExtractionConfig>(),
        });
        let __alef_values = match acquire_handles(&__alef_requests) {
            Ok(values) => values,
            Err(error) => {
                set_handle_error(&error);
                return -1;
            }
        };
        let mut __alef_guards = Vec::with_capacity(__alef_values.len());
        for (handle, value) in &__alef_values {
            match value.lock() {
                Ok(guard) => __alef_guards.push((*handle, guard)),
                Err(_) => {
                    set_handle_error(&HandleError::RegistryPoisoned);
                    return -1;
                }
            }
        }
        if this == 0 {
            set_last_error(ALEF_INVALID_HANDLE_ERROR, "zero is not a valid handle");
            return -1;
        }
        let obj_ptr = match locked_handle_ptr::<xberg::ExtractionConfig>(&mut __alef_guards, this) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return -1;
            }
        };
        // SAFETY: the registry entry guard remains held for the duration of this call.
        let obj = unsafe { &*obj_ptr };

        let result = obj.validate();
        match result {
            Ok(()) => 0,
            Err(e) => {
                set_last_error(alef_ffi_error_code(&e), &e.to_string());
                -1
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            -1
        }
    }
}

