/// Get the server listen address (host:port).
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
/// \code
/// use xberg::core::ServerConfig;
///
/// let config = ServerConfig::default();
/// assert_eq!(config.listen_addr(), "127.0.0.1:8000");
/// \endcode
#[cfg(feature = "api-types")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn xberg_server_config_listen_addr(this: AlefHandle) -> *mut std::ffi::c_char {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut __alef_requests: Vec<HandleRequest> = Vec::new();
        __alef_requests.push(HandleRequest {
            handle: this,
            expected_type: std::any::TypeId::of::<xberg::ServerConfig>(),
        });
        let __alef_values = match acquire_handles(&__alef_requests) {
            Ok(values) => values,
            Err(error) => {
                set_handle_error(&error);
                return std::ptr::null_mut();
            }
        };
        let mut __alef_guards = Vec::with_capacity(__alef_values.len());
        for (handle, value) in &__alef_values {
            match value.lock() {
                Ok(guard) => __alef_guards.push((*handle, guard)),
                Err(_) => {
                    set_handle_error(&HandleError::RegistryPoisoned);
                    return std::ptr::null_mut();
                }
            }
        }
        if this == 0 {
            set_last_error(ALEF_INVALID_HANDLE_ERROR, "zero is not a valid handle");
            return std::ptr::null_mut();
        }
        let obj_ptr = match locked_handle_ptr::<xberg::ServerConfig>(&mut __alef_guards, this) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return std::ptr::null_mut();
            }
        };
        // SAFETY: the registry entry guard remains held for the duration of this call.
        let obj = unsafe { &*obj_ptr };

        let result = obj.listen_addr();
        match CString::new(result.to_string()) {
            Ok(cs) => cs.into_raw(),
            Err(_) => {
                set_last_error(
                    ALEF_FFI_CONVERSION_ERROR,
                    "FFI field value contains an interior NUL byte",
                );
                std::ptr::null_mut()
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            std::ptr::null_mut()
        }
    }
}

