/// Set whether to parse the citation block.
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
#[cfg(feature = "markdown-footnotes")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn xberg_footnote_config_with_parse_citations(this: AlefHandle, enabled: i32) -> AlefHandle {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut __alef_requests: Vec<HandleRequest> = Vec::new();

        if __alef_requests.iter().any(|request| request.handle == this) {
            set_handle_error(&HandleError::AliasedHandle);
            return 0;
        }
        let __alef_values = match acquire_handles(&__alef_requests) {
            Ok(values) => values,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        let mut __alef_guards = Vec::with_capacity(__alef_values.len());
        for (handle, value) in &__alef_values {
            match value.lock() {
                Ok(guard) => __alef_guards.push((*handle, guard)),
                Err(_) => {
                    set_handle_error(&HandleError::RegistryPoisoned);
                    return 0;
                }
            }
        }
        if this == 0 {
            set_last_error(ALEF_INVALID_HANDLE_ERROR, "zero is not a valid handle");
            return 0;
        }
        if __alef_values.iter().any(|(handle, _)| *handle == this) {
            set_handle_error(&HandleError::AliasedHandle);
            return 0;
        }
        let obj = match take_handle::<xberg::FootnoteConfig>(this) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };

        let enabled_rs = enabled != 0;

        let result = obj.with_parse_citations(enabled_rs);
        match insert_handle(result) {
            Ok(handle) => handle,
            Err(error) => {
                set_handle_error(&error);
                0
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            0
        }
    }
}

