/// Compute and populate the `node_types` field from the current `nodes`.
///
/// Call this after all nodes have been added to the structure. Internal
/// construction paths (builder, derivation) call this automatically.
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
/// \code
/// use xberg::types::document_structure::{DocumentStructure, DocumentNode, NodeContent};
///
/// let mut structure = DocumentStructure {
///     nodes: vec![DocumentNode {
///         id: String::new(),
///         content: NodeContent::Paragraph { text: "Hello".into() },
///         parent: None,
///         children: vec![],
///         content_layer: Default::default(),
///         page: None,
///         page_end: None,
///         bbox: None,
///         annotations: vec![],
///         attributes: None,
///     }],
///     source_format: None,
///     relationships: vec![],
///     node_types: vec![],
/// };
/// structure.finalize_node_types();
/// assert!(structure.node_types.contains(&"paragraph".to_string()));
/// \endcode
#[unsafe(no_mangle)]
pub unsafe extern "C" fn xberg_document_structure_finalize_node_types(this: AlefHandle) {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut __alef_requests: Vec<HandleRequest> = Vec::new();
        __alef_requests.push(HandleRequest {
            handle: this,
            expected_type: std::any::TypeId::of::<xberg::DocumentStructure>(),
        });
        let __alef_values = match acquire_handles(&__alef_requests) {
            Ok(values) => values,
            Err(error) => {
                set_handle_error(&error);
                return;
            }
        };
        let mut __alef_guards = Vec::with_capacity(__alef_values.len());
        for (handle, value) in &__alef_values {
            match value.lock() {
                Ok(guard) => __alef_guards.push((*handle, guard)),
                Err(_) => {
                    set_handle_error(&HandleError::RegistryPoisoned);
                    return;
                }
            }
        }
        if this == 0 {
            set_last_error(ALEF_INVALID_HANDLE_ERROR, "zero is not a valid handle");
            return;
        }
        let obj_ptr = match locked_handle_ptr::<xberg::DocumentStructure>(&mut __alef_guards, this) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return;
            }
        };
        // SAFETY: the registry entry guard remains held for the duration of this call.
        let obj = unsafe { &mut *obj_ptr };

        let result = obj.finalize_node_types();
    })) {
        Ok(value) => value,
        Err(_) => {
            let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            ()
        }
    }
}

