/// Returns `true` if `data` holds exactly `num_tokens * dim` values â i.e.
/// the flat buffer matches the declared shape.
///
/// All fields are `pub` and the type is `Deserialize`, so a value coming
/// from an untrusted source (FFI caller, JSON, a store row) may be
/// malformed. `max_sim_score` guards on this so a length-mismatched
/// buffer scores `0.0` rather than silently mis-scoring (a shorter `data`
/// would make `rows` (Self::rows)' `chunks_exact` drop a trailing partial
/// chunk). Uses `checked_mul` so an overflowing `num_tokens * dim` is
/// reported as malformed instead of wrapping.
///
/// Since v5.0.0.
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
#[cfg(feature = "late-interaction-presets")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn xberg_multi_vector_embedding_is_well_formed(this: AlefHandle) -> i32 {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut __alef_requests: Vec<HandleRequest> = Vec::new();
        __alef_requests.push(HandleRequest {
            handle: this,
            expected_type: std::any::TypeId::of::<xberg::MultiVectorEmbedding>(),
        });
        let __alef_values = match acquire_handles(&__alef_requests) {
            Ok(values) => values,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        let mut __alef_guards = Vec::with_capacity(__alef_values.len());
        for (handle, value) in &__alef_values {
            match value.lock() {
                Ok(guard) => __alef_guards.push((*handle, guard)),
                Err(_) => {
                    set_handle_error(&HandleError::RegistryPoisoned);
                    return 0;
                }
            }
        }
        if this == 0 {
            set_last_error(ALEF_INVALID_HANDLE_ERROR, "zero is not a valid handle");
            return 0;
        }
        let obj_ptr = match locked_handle_ptr::<xberg::MultiVectorEmbedding>(&mut __alef_guards, this) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        // SAFETY: the registry entry guard remains held for the duration of this call.
        let obj = unsafe { &*obj_ptr };

        let result = obj.is_well_formed();
        if result { 1 } else { 0 }
    })) {
        Ok(value) => value,
        Err(_) => {
            let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            0
        }
    }
}

