/// The returned string must be freed with `xberg_free_string`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn xberg_crawl_config_to_json(handle: AlefHandle) -> *mut c_char {
    catch_ffi_panic(std::ptr::null_mut(), || {
        clear_last_error();
        if handle == 0 {
            set_last_error(ALEF_INVALID_HANDLE_ERROR, "zero is not a valid handle");
            return std::ptr::null_mut();
        }
        match with_handle::<crawlberg::CrawlConfig, _>(handle, serde_json::to_string) {
            Err(error) => {
                set_handle_error(&error);
                std::ptr::null_mut()
            }
            Ok(Err(error)) => {
                set_last_error(2, &error.to_string());
                std::ptr::null_mut()
            }
            Ok(Ok(s)) => match CString::new(s) {
                Ok(cs) => cs.into_raw(),
                Err(e) => {
                    set_last_error(2, &e.to_string());
                    std::ptr::null_mut()
                }
            },
        }
    })
}

/// Free a `CrawlConfig` handle.
/// # Safety
/// Handle must have been returned by this library, or be zero.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn xberg_crawl_config_free(handle: AlefHandle) {
    catch_ffi_panic((), || {
        if handle != 0 {
            if let Err(error) = remove_handle::<crawlberg::CrawlConfig>(handle) {
                set_handle_error(&error);
            }
        }
    })
}

