fn get_ffi_runtime() -> &'static tokio::runtime::Runtime {
    use std::sync::OnceLock;
    static RUNTIME: OnceLock<tokio::runtime::Runtime> = OnceLock::new();
    RUNTIME.get_or_init(|| tokio::runtime::Runtime::new().expect("Failed to create tokio runtime"))
}

/// Extract content from a single bytes or URI input.
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn xberg_extract(input: AlefHandle, config: AlefHandle) -> AlefHandle {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut __alef_requests: Vec<HandleRequest> = Vec::new();
        __alef_requests.push(HandleRequest {
            handle: input,
            expected_type: std::any::TypeId::of::<xberg::ExtractInput>(),
        });
        __alef_requests.push(HandleRequest {
            handle: config,
            expected_type: std::any::TypeId::of::<xberg::ExtractionConfig>(),
        });
        let __alef_values = match acquire_handles(&__alef_requests) {
            Ok(values) => values,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        let mut __alef_guards = Vec::with_capacity(__alef_values.len());
        for (handle, value) in &__alef_values {
            match value.lock() {
                Ok(guard) => __alef_guards.push((*handle, guard)),
                Err(_) => {
                    set_handle_error(&HandleError::RegistryPoisoned);
                    return 0;
                }
            }
        }
        if input == 0 {
            set_last_error(
                ALEF_INVALID_HANDLE_ERROR,
                "zero is not a valid handle for parameter 'input'",
            );
            return 0;
        }
        let input_rs_ptr = match locked_handle_ptr::<xberg::ExtractInput>(&mut __alef_guards, input) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        // SAFETY: the registry entry guard remains held for the duration of this call.
        let input_rs = unsafe { &*input_rs_ptr }.clone();

        if config == 0 {
            set_last_error(
                ALEF_INVALID_HANDLE_ERROR,
                "zero is not a valid handle for parameter 'config'",
            );
            return 0;
        }
        let config_rs_ptr = match locked_handle_ptr::<xberg::ExtractionConfig>(&mut __alef_guards, config) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        // SAFETY: the registry entry guard remains held for the duration of this call.
        let config_rs = unsafe { &*config_rs_ptr };

        let result = get_ffi_runtime().block_on(async { xberg::extract(input_rs, &config_rs).await });
        match result {
            Ok(val) => match insert_handle(val) {
                Ok(handle) => handle,
                Err(error) => {
                    set_handle_error(&error);
                    0
                }
            },
            Err(e) => {
                set_last_error(alef_ffi_error_code(&e), &e.to_string());
                0
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            0
        }
    }
}

