/// Run chunk classification against an extraction result.
///
/// Mutates `ChunkMetadata::classifications` on every chunk in
/// `result.chunks` and appends every LLM call's usage to `result.llm_usage`.
/// A chunk whose classification batch call fails (or that the model omitted
/// from its response) is simply left with an empty `classifications` vector for
/// that chunk, unless the failure is a validation error (empty config) or every
/// batch task fails, in which case the first error is returned.
/// \note Returns `Validation` when `config.definitions` is empty.
/// Returns the first batch error encountered when rendering the prompt or
/// calling the LLM fails for every batch; partial failures on a subset of
/// batches are recorded here as a `ProcessingWarning` on `result` instead of
/// aborting the whole run.
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn xberg_classify_chunks(result: AlefHandle, config: AlefHandle) -> i32 {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut __alef_requests: Vec<HandleRequest> = Vec::new();
        __alef_requests.push(HandleRequest {
            handle: result,
            expected_type: std::any::TypeId::of::<xberg::ExtractedDocument>(),
        });
        __alef_requests.push(HandleRequest {
            handle: config,
            expected_type: std::any::TypeId::of::<xberg::ChunkClassificationConfig>(),
        });
        let __alef_values = match acquire_handles(&__alef_requests) {
            Ok(values) => values,
            Err(error) => {
                set_handle_error(&error);
                return -1;
            }
        };
        let mut __alef_guards = Vec::with_capacity(__alef_values.len());
        for (handle, value) in &__alef_values {
            match value.lock() {
                Ok(guard) => __alef_guards.push((*handle, guard)),
                Err(_) => {
                    set_handle_error(&HandleError::RegistryPoisoned);
                    return -1;
                }
            }
        }
        if result == 0 {
            set_last_error(
                ALEF_INVALID_HANDLE_ERROR,
                "zero is not a valid handle for parameter 'result'",
            );
            return -1;
        }
        let result_rs_ptr = match locked_handle_ptr::<xberg::ExtractedDocument>(&mut __alef_guards, result) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return -1;
            }
        };
        // SAFETY: the registry entry guard remains held for the duration of this call.
        let result_rs = unsafe { &mut *result_rs_ptr };

        if config == 0 {
            set_last_error(
                ALEF_INVALID_HANDLE_ERROR,
                "zero is not a valid handle for parameter 'config'",
            );
            return -1;
        }
        let config_rs_ptr = match locked_handle_ptr::<xberg::ChunkClassificationConfig>(&mut __alef_guards, config) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return -1;
            }
        };
        // SAFETY: the registry entry guard remains held for the duration of this call.
        let config_rs = unsafe { &*config_rs_ptr };

        let result = get_ffi_runtime()
            .block_on(async { xberg::text::classification::classify_chunks(result_rs, &config_rs).await });
        match result {
            Ok(()) => 0,
            Err(e) => {
                set_last_error(alef_ffi_error_code(&e), &e.to_string());
                -1
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            -1
        }
    }
}

/// Find unmarked claims in markdown text.
///
/// Returns lines that assert a claim but carry neither a footnote citation anchor (`[^...]`)
/// nor an inference marker (`[*inference*]`).
///
/// The heuristic is simple: a line that contains alphabetic words, ends with sentence punctuation,
/// and is not a heading, blank line, or markup-only line is considered a claim.
/// Exclude lines that appear in the citation block (after `---` + `<!-- citations ... -->`).
/// \param markdown The markdown text to search
/// \return A vector of trimmed line text strings for unmarked claims.
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
/// \code
/// let text = r#"This is a claim without citation.
/// Another claim with citation.[^1]
/// This is a claim with inference.[*inference*]
///
/// [^1]: Citation"#;
/// let unmarked = find_unmarked_claims(text);
/// assert_eq!(unmarked.len(), 1);
/// assert!(unmarked[0].contains("without citation"));
/// \endcode
#[cfg(feature = "markdown-footnotes")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn xberg_find_unmarked_claims(markdown: *const std::ffi::c_char) -> *mut std::ffi::c_char {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        set_last_return_len("xberg_find_unmarked_claims", 0);
        if markdown.is_null() {
            set_last_error(1, "Null pointer passed for parameter 'markdown'");
            return std::ptr::null_mut();
        }
        // SAFETY: null check above guarantees markdown is a valid pointer; string is valid UTF-8 from caller.
        let markdown_rs = match unsafe { CStr::from_ptr(markdown) }.to_str() {
            Ok(s) => s.to_string(),
            Err(_) => {
                set_last_error(1, "Invalid UTF-8 in parameter 'markdown'");
                return std::ptr::null_mut();
            }
        };

        let result = xberg::find_unmarked_claims(&markdown_rs);
        {
            match serde_json::to_string(&result) {
                Ok(__alef_return) => match CString::new(__alef_return) {
                    Ok(cs) => {
                        set_last_return_len("xberg_find_unmarked_claims", cs.as_bytes().len());
                        cs.into_raw()
                    }
                    Err(_) => {
                        set_last_return_len("xberg_find_unmarked_claims", 0);
                        std::ptr::null_mut()
                    }
                },
                Err(_) => {
                    set_last_return_len("xberg_find_unmarked_claims", 0);
                    std::ptr::null_mut()
                }
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            std::ptr::null_mut()
        }
    }
}

