#[unsafe(no_mangle)]
pub unsafe extern "C" fn xberg_build_decoder_prompt_tokens(
    start_of_transcript: u32,
    lang_id: u32,
    transcribe: u32,
    no_timestamps: u32,
    timestamps: i32,
) -> *mut std::ffi::c_char {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        set_last_return_len("xberg_build_decoder_prompt_tokens", 0);
        let start_of_transcript_rs = start_of_transcript;

        let lang_id_rs = lang_id;

        let transcribe_rs = transcribe;

        let no_timestamps_rs = no_timestamps;

        let timestamps_rs = timestamps != 0;

        let result = xberg::transcription::engine::build_decoder_prompt_tokens(
            start_of_transcript_rs,
            lang_id_rs,
            transcribe_rs,
            no_timestamps_rs,
            timestamps_rs,
        );
        {
            match serde_json::to_string(&result) {
                Ok(__alef_return) => match CString::new(__alef_return) {
                    Ok(cs) => {
                        set_last_return_len("xberg_build_decoder_prompt_tokens", cs.as_bytes().len());
                        cs.into_raw()
                    }
                    Err(_) => {
                        set_last_return_len("xberg_build_decoder_prompt_tokens", 0);
                        std::ptr::null_mut()
                    }
                },
                Err(_) => {
                    set_last_return_len("xberg_build_decoder_prompt_tokens", 0);
                    std::ptr::null_mut()
                }
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            std::ptr::null_mut()
        }
    }
}

/// Return the byte length of the C string most recently returned by `xberg_build_decoder_prompt_tokens`
