#[async_trait::async_trait]
impl xberg::DocumentExtractor for XbergDocumentExtractorBridge {
    async fn extract(
        &self,
        input: xberg::ExtractInput,
        config: &xberg::ExtractionConfig,
    ) -> std::result::Result<xberg::ExtractedDocument, xberg::XbergError> {
        struct _SendFn<F>(F);
        // SAFETY: caller guarantees vtable fn pointers and user_data are valid across threads.
        unsafe impl<F> Send for _SendFn<F> {}
        impl<F: FnOnce() -> R, R> _SendFn<F> {
            fn call(self) -> R {
                (self.0)()
            }
        }

        let _cached_name = self.cached_name.clone();
        let vtable = self.vtable;
        let user_data = self.user_data;
        let input = input.clone();
        let config = config.clone();

        let _task = _SendFn(move || {
            // Inline the sync body:
            let Some(fp) = vtable.extract else {
                return Err(Box::from("vtable.extract is null — bridge not initialised"));
            };
            let _input_json = serde_json::to_string(&input).unwrap_or_default();
            let _input_cs = match std::ffi::CString::new(_input_json) {
                Ok(s) => s,
                Err(_) => {
                    return Err(Box::from("nul byte in serialized param input"));
                }
            };
            let input_ptr = _input_cs.as_ptr();
            let _config_json = serde_json::to_string(&config).unwrap_or_default();
            let _config_cs = match std::ffi::CString::new(_config_json) {
                Ok(s) => s,
                Err(_) => {
                    return Err(Box::from("nul byte in serialized param config"));
                }
            };
            let config_ptr = _config_cs.as_ptr();
            let mut _out_result: *mut std::ffi::c_char = std::ptr::null_mut();
            let mut _out_error: *mut std::ffi::c_char = std::ptr::null_mut();
            // SAFETY: fp is a valid non-null function pointer; all temporaries outlive this call;
            // user_data validity is the caller's responsibility (documented in the vtable API).
            let _rc = unsafe { fp(user_data, input_ptr, config_ptr, &mut _out_result, &mut _out_error) };
            if _rc != 0 {
                let msg = if _out_error.is_null() {
                    format!("vtable.extract returned error code {}", _rc)
                } else {
                    // SAFETY: out_error was written by the callee as a valid NUL-terminated string.
                    let msg = unsafe { std::ffi::CStr::from_ptr(_out_error) }
                        .to_string_lossy()
                        .into_owned();
                    if let Some(free_fn) = vtable.free_string {
                        // SAFETY: free_fn is the vtable-provided destructor for callback strings.
                        unsafe { free_fn(_out_error) };
                    }
                    msg
                };
                return Err(Box::from(msg));
            }
            if _out_result.is_null() {
                return Err(Box::from("vtable.extract returned null out_result"));
            }
            // SAFETY: out_result was written by the callee as a valid NUL-terminated string.
            let json = unsafe { std::ffi::CStr::from_ptr(_out_result) }
                .to_string_lossy()
                .into_owned();
            if let Some(free_fn) = vtable.free_string {
                // SAFETY: free_fn is the vtable-provided destructor for callback strings.
                unsafe { free_fn(_out_result) };
            }
            serde_json::from_str::<xberg::ExtractedDocument>(&json)
                .map_err(|e| Box::from(e.to_string()) as Box<dyn std::error::Error + Send + Sync>)
        });
        tokio::task::spawn_blocking(move || _task.call())
            .await
            .map_err(|e| xberg::XbergError::Other(format!("spawn_blocking failed in extract: {}", e)))?
            .map_err(|e: Box<dyn std::error::Error + Send + Sync>| xberg::XbergError::Other(e.to_string()))
    }

    fn supported_mime_types(&self) -> &[&str] {
        self.supported_mime_types_strs
    }

    fn priority(&self) -> i32 {
        let Some(fp) = self.vtable.priority else {
            tracing::warn!(
                wrapper = "XbergDocumentExtractorBridge",
                method = "priority",
                "vtable slot for host callback is not initialised; returning default"
            );
            return 0;
        };
        // SAFETY: fp is a valid non-null function pointer; all temporaries outlive this call;
        // user_data validity is the caller's responsibility (documented in the vtable API).
        unsafe { fp(self.user_data) }
    }

    fn can_handle(&self, _path: &std::path::Path, _mime_type: &str) -> bool {
        let Some(fp) = self.vtable.can_handle else {
            tracing::warn!(
                wrapper = "XbergDocumentExtractorBridge",
                method = "can_handle",
                "vtable slot for host callback is not initialised; returning default"
            );
            return false;
        };
        let __path_cs = match std::ffi::CString::new(_path.to_string_lossy().as_ref()) {
            Ok(s) => s,
            Err(_) => {
                return false;
            }
        };
        let _path_ptr = __path_cs.as_ptr();
        let __mime_type_cs = match std::ffi::CString::new(_mime_type) {
            Ok(s) => s,
            Err(_) => {
                return false;
            }
        };
        let _mime_type_ptr = __mime_type_cs.as_ptr();
        // SAFETY: fp is a valid non-null function pointer; all temporaries outlive this call;
        // user_data validity is the caller's responsibility (documented in the vtable API).
        let _rc = unsafe { fp(self.user_data, _path_ptr, _mime_type_ptr) };
        _rc != 0
    }
}

/// Register a C plugin implementing `DocumentExtractor` via a vtable.
///
/// # Parameters
///
/// - `name`: null-terminated UTF-8 plugin name. Must not be null.
/// - `vtable`: vtable with function pointers implementing the trait.
/// - `user_data`: opaque pointer forwarded to every vtable function.
/// - `out_error`: receives a heap-allocated error string on failure.
///
/// # Safety
///
/// All function pointers in `vtable` must remain valid until the plugin is
/// unregistered. `user_data` must be safe to use from any thread that calls
/// into the plugin.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn xberg_register_document_extractor(
    name: *const std::ffi::c_char,
    vtable: *const XbergDocumentExtractorVTable,
    user_data: *const std::ffi::c_void,
    out_error: *mut *mut std::ffi::c_char,
) -> i32 {
    catch_ffi_panic(1, || {
        if name.is_null() {
            // SAFETY: out_error is validated by ffi_set_out_error itself (null-checked internally).
            unsafe { ffi_set_out_error(out_error, "name must not be null") };
            return 1;
        }
        if vtable.is_null() {
            // SAFETY: out_error is validated by ffi_set_out_error itself (null-checked internally).
            unsafe { ffi_set_out_error(out_error, "vtable must not be null") };
            return 1;
        }
        // SAFETY: null check above guarantees vtable is a valid pointer.
        let vtable_ref = unsafe { &*vtable };
        if vtable_ref.free_string.is_none() {
            // SAFETY: out_error is validated by ffi_set_out_error itself (null-checked internally).
            unsafe { ffi_set_out_error(out_error, "vtable.free_string must not be null") };
            return 1;
        }
        if vtable_ref.extract.is_none() {
            // SAFETY: out_error is validated by ffi_set_out_error itself (null-checked internally).
            unsafe { ffi_set_out_error(out_error, "vtable.extract must not be null") };
            return 1;
        }
        if vtable_ref.supported_mime_types.is_none() {
            // SAFETY: out_error is validated by ffi_set_out_error itself (null-checked internally).
            unsafe { ffi_set_out_error(out_error, "vtable.supported_mime_types must not be null") };
            return 1;
        }

        // SAFETY: name is non-null (checked above); it points to a valid C string.
        let plugin_name = match unsafe { std::ffi::CStr::from_ptr(name) }.to_str() {
            Ok(s) => s.to_owned(),
            Err(_) => {
                // SAFETY: out_error is validated by ffi_set_out_error itself (null-checked internally).
                unsafe { ffi_set_out_error(out_error, "name is not valid UTF-8") };
                return 1;
            }
        };

        // SAFETY: vtable pointer and user_data validity is the caller's responsibility.
        let bridge = unsafe { XbergDocumentExtractorBridge::new(plugin_name, *vtable_ref, user_data) };
        let arc: Arc<dyn xberg::DocumentExtractor> = Arc::new(bridge);

        let registry = xberg::plugins::registry::get_document_extractor_registry();
        let mut registry = registry.write();

        if let Err(e) = registry.register(arc) {
            // SAFETY: out_error is validated by ffi_set_out_error itself (null-checked internally).
            unsafe { ffi_set_out_error(out_error, &e.to_string()) };
            return 1;
        }
        0
    })
}

/// Unregister a previously registered C plugin by name.
///
/// # Parameters
///
/// - `name`: null-terminated UTF-8 plugin name. Must not be null.
/// - `out_error`: receives a heap-allocated error string on failure.
///
/// # Safety
